 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in('public','s01_i02','brand_b1','brand_b2','composio_c1') and p.prokind='f'),
policies as(select n.nspname||'.'||c.relname||'.'||p.polname key,jsonb_build_object('relation',n.nspname||'.'||c.relname,'command',p.polcmd,'permissive',p.polpermissive,'roles',(select jsonb_agg(case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end order by case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end) from unnest(p.polroles) r),'usingHash',md5(pg_get_expr(p.polqual,p.polrelid)),'checkHash',md5(pg_get_expr(p.polwithcheck,p.polrelid))) value from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','storage')),
triggers as(select n.nspname||'.'||c.relname||'.'||t.tgname key,jsonb_build_object('relation',n.nspname||'.'||c.relname,'enabled',t.tgenabled,'hash',md5(pg_get_triggerdef(t.oid))) value from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','storage') and not t.tgisinternal),
constraints as(select n.nspname||'.'||c.relname||'.'||x.conname key,jsonb_build_object('relation',n.nspname||'.'||c.relname,'kind',x.contype,'validated',x.convalidated,'hash',md5(pg_get_constraintdef(x.oid))) value from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and x.contype<>'n'),
indexes as(select schemaname||'.'||indexname key,jsonb_build_object('relation',schemaname||'.'||tablename,'hash',md5(indexdef)) value from pg_indexes where schemaname in('public','storage')),
schemas as(select nspname key,jsonb_build_object('owner',pg_get_userbyid(nspowner),'access',(select jsonb_object_agg(r.name,jsonb_build_array(has_schema_privilege(r.name,n.oid,'USAGE'),has_schema_privilege(r.name,n.oid,'CREATE'))) from roles r),'publicAccess',exists(select 1 from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x where x.grantee=0)) value from pg_namespace n where nspname in('s01_i02','brand_b1','brand_b2','composio_c1'))
select jsonb_build_object('relations',(select coalesce(jsonb_object_agg(key,value order by key),'{}') from relations),'functions',(select coalesce(jsonb_object_agg(key,value order by key),'{}') from functions),'policies',(select coalesce(jsonb_object_agg(key,value order by key),'{}') from policies),'triggers',(select coalesce(jsonb_object_agg(key,value order by key),'{}') from triggers),'constraints',(select coalesce(jsonb_object_agg(key,value order by key),'{}') from constraints),'indexes',(select coalesce(jsonb_object_agg(key,value order by key),'{}') from indexes),'schemas',(select coalesce(jsonb_object_agg(key,value order by key),'{}') from schemas)) snapshot) x;for g in select jsonb_object_keys(expected) loop
 for k,v in select * from jsonb_each(expected->g) loop
 a:=coalesce(observed->g->k,'null'::jsonb);
 if g='functions' and v<>'null'::jsonb then
  if (a-'sourceHash') is distinct from (v-'sourceHash') or not coalesce((case when mode='pre' then d->'sourceVariants'->k else coalesce(d->'postSourceVariants'->k,jsonb_build_array(v->>'sourceHash')) end)?(a->>'sourceHash'),false) then ok:=false;end if;
 elsif a is distinct from v then ok:=false;end if;
 end loop;end loop;
 if coalesce((select jsonb_object_agg(fn_name,true) from jsonb_object_keys(observed->'functions') fn_name),'{}'::jsonb) is distinct from (select coalesce(jsonb_object_agg(fn_name,true),'{}'::jsonb) from jsonb_array_elements_text(d->'finalFunctionNames') fn_name) then ok:=false;end if;
 if not ok then
 for g in select jsonb_object_keys(expected) order by 1 loop
  for k,v in select * from jsonb_each(expected->g) order by key loop
   a:=coalesce(observed->g->k,'null'::jsonb);
   if v='null'::jsonb or a='null'::jsonb then
    if a is distinct from v then
     fd_count:=fd_count+1;
     if jsonb_array_length(fd_details)<40 then
      fd_details:=fd_details||jsonb_build_array(jsonb_build_object('group',g,'object',left(k,256),'field','presence'));
     end if;
    end if;
   else
    for fd_field in select jsonb_object_keys(v) union select jsonb_object_keys(a) order by 1 loop
     if g='functions' and fd_field='sourceHash'
      and coalesce((coalesce(d->'postSourceVariants'->k,jsonb_build_array(v->>'sourceHash')))?(a->>'sourceHash'),false) then continue;end if;
     if a->fd_field is distinct from v->fd_field then
      fd_count:=fd_count+1;
      if jsonb_array_length(fd_details)<40 then
       fd_details:=fd_details||jsonb_build_array(jsonb_build_object('group',g,'object',left(k,256),'field',fd_field,
        'expectedFingerprint',md5(coalesce((v->fd_field)::text,'SQL_NULL')),
        'observedFingerprint',md5(coalesce((a->fd_field)::text,'SQL_NULL'))));
      end if;
     end if;
    end loop;
   end if;
  end loop;
 end loop;
 select count(*),coalesce(jsonb_agg(key order by key) filter(where ordinal<=20),'[]') into fd_missing_count,fd_missing
 from (select key,row_number() over(order by key) ordinal from jsonb_array_elements_text(d->'finalFunctionNames') key
  where not (observed->'functions')?key) missing;
 select count(*),coalesce(jsonb_agg(key order by key) filter(where ordinal<=20),'[]') into fd_extra_count,fd_extra
 from (select key,row_number() over(order by key) ordinal from jsonb_object_keys(observed->'functions') key
  where not (d->'finalFunctionNames')?key) extra;
 fd_inventory_ok:=fd_missing_count=0 and fd_extra_count=0;
 fd_report:=jsonb_build_object('protocol','AF-FDIAG-r1','ordinal','049','stage','failed_before_commit',
  'sourceMigrationSha256','19548594e04d95167ed23957264f25d796a0f5f02e9427c75bf1f53f4fd390aa','contractSha256','6fc8d3de046552f2f066abfb814b1929141ea2c3547d6762e0e7e1bfb820e4af',
  'version',current_setting('server_version_num'),'collation',(select datcollate from pg_database where datname=current_database()),
  'mismatchCount',fd_count+fd_missing_count+fd_extra_count,'fieldMismatchCount',fd_count,
  'details',fd_details,'detailsTruncated',fd_count>jsonb_array_length(fd_details),
  'functionInventory',jsonb_build_object('ok',fd_inventory_ok,'missingCount',fd_missing_count,'extraCount',fd_extra_count,
   'missingFirst20',fd_missing,'extraFirst20',fd_extra,'truncated',fd_missing_count>20 or fd_extra_count>20),
  'allGuardsRetained',true,'commitAllowed',false);
 raise exception using errcode='P0001',message='ABC_FINAL_CONTRACT_MISMATCH',detail=fd_report::text,
  hint='Conservar DETAIL. No reintentar 049. Limpiar la transaccion fallida con ROLLBACK.';
end if;
 fingerprint:=(select md5(jsonb_build_object(
 'untouched',(select jsonb_object_agg(e.key,(case when e.key='functions' then (select coalesce(jsonb_object_agg(f.key,case when coalesce((d->'protectedSourceVariants'->f.key)?(f.value->>'sourceHash'),false) then jsonb_set(f.value,'{sourceHash}',d->'protectedSourceVariants'->f.key->0,false) else f.value end),'{}'::jsonb) from jsonb_each(e.value) f) else e.value end)-coalesce(array(select jsonb_array_elements_text(d->'changed'->e.key)),array[]::text[])) from jsonb_each(observed) e),
 'roles',(select jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls) order by rolname) from pg_roles),
 'memberships',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor),admin_option) order by roleid,member) from pg_auth_members),
 'defaults',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(defaclrole),coalesce(n.nspname,'GLOBAL'),defaclobjtype,defaclacl::text) order by defaclrole,defaclnamespace,defaclobjtype) from pg_default_acl x left join pg_namespace n on n.oid=x.defaclnamespace),
 'platformSchemas',(select jsonb_agg(jsonb_build_array(nspname,pg_get_userbyid(nspowner),nspacl::text) order by nspname) from pg_namespace where nspname in('public','auth','storage')),
 'storageConstraints',(select jsonb_agg(jsonb_build_array(c.relname,x.conname,pg_get_constraintdef(x.oid)) order by c.relname,x.conname) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='storage')
 )::text));
 if fingerprint is distinct from current_setting('pipeline_os.abc_protected_before',true) then raise exception 'ABC_PROTECTED_METADATA_CHANGED';end if;
 perform set_config('pipeline_os.abc_receipt',jsonb_build_object('protocol','ABC-FINAL-r1','ordinal','049','stage','checked_before_commit','contractSha256','6fc8d3de046552f2f066abfb814b1929141ea2c3547d6762e0e7e1bfb820e4af','targetsOk',true,'protectedBefore',current_setting('pipeline_os.abc_protected_before'),'protectedAfter',fingerprint,'preservationMatches',true,'gmailProviderExpected','gmail_oauth','composioEnabledExpected',false)::text,true);
end $af_check$;
select jsonb_build_object('protocol','AF-FDIAG-r1','ordinal','049','stage','checked_before_rollback',
 'sourceMigrationSha256','19548594e04d95167ed23957264f25d796a0f5f02e9427c75bf1f53f4fd390aa','contractSha256','6fc8d3de046552f2f066abfb814b1929141ea2c3547d6762e0e7e1bfb820e4af',
 'version',current_setting('server_version_num'),'mismatchCount',0,'commitAllowed',false,
 'protectedBefore',current_setting('pipeline_os.abc_protected_before'),
 'protectedAfter',(current_setting('pipeline_os.abc_receipt')::jsonb)->>'protectedAfter') pipeline_os_abc_final_diagnostic;
rollback;
